void CrateCollide::onCollide(Object *other,const Coord3D *,const Coord3D *)
{
    const CrateCollideModuleData *data=getCrateCollideModuleData();
    if (isValidToExecute(other)) {
        if (executeCrateBehavior(other)) {
            if (data->m_executeFX) FXList::doFXObj(data->m_executeFX,other,0);
            m_everExecuted=true;
            TheGameLogic->destroyObject(getObject());
        }
        if (TheAnim2DCollection && !data->m_executeAnimation.isEmpty() && TheGameLogic->getDrawIconUI()) {
            Anim2DTemplate *animation=TheAnim2DCollection->findTemplate(data->m_executeAnimation);
            TheInGameUI->addWorldAnimation(animation,getObject()->getPosition(),WORLD_ANIM_FADE_ON_EXPIRE,
                data->m_executeAnimationTime,data->m_executeAnimationZRise);
        }
    }
}

