        bool validBuildingAttempt=data->m_buildingPickup && (other->getTemplate()->isKindOf(KINDOF_STRUCTURE));
        if (!other->getAIUpdateInterface() && !validBuildingAttempt) return false;
        if (other->getTemplate()->isKindOf(KINDOF_CREEP)) {
            Player *controller=other->getControllingPlayer();
            if (!controller) return false;
            if (!controller->rva002AA245()) return false;
        }
        if (!other->isKindOfMulti(data->m_requiredKindOf,data->m_forbiddenKindOf)) return false;
        if (other->isEffectivelyDead()) return false;
        if (getObject()->isAboveTerrain() && !validBuildingAttempt) return false;
        if (data->m_forbidOwnerPlayer && getObject()->getControllingPlayer()==other->getControllingPlayer()) return false;
        if (data->m_humanOnly && other->getControllingPlayer() && other->getControllingPlayer()->m_playerType!=0) return false;
        if (data->m_pickupScience!=-1 && other->getControllingPlayer() && !other->getControllingPlayer()->hasScience((ScienceType)data->m_pickupScience)) return false;
